<!DOCTYPE html>
<html>
<head>
<style>
    body {
        background: #0d0d0d;
        color: #fff;
        font-family: Arial, sans-serif;
        margin: 0;
        padding: 20px;
        display: flex;
        justify-content: center;
        align-items: center;
        min-height: 100vh;
    }

    #life {
        border: 2px solid #3a3a3a;
        cursor: crosshair;
        background-color: #151515;
    }

    .controls {
        margin-top: 20px;
        display: flex;
        gap: 10px;
        justify-content: center;
    }

    button {
        padding: 12px 24px;
        font-size: 16px;
        border: none;
        border-radius: 5px;
        background-color: #3a3a3a;
        color: white;
        cursor: pointer;
        transition: all 0.3s;
    }

    button:hover {
        background-color: #4d4d4d;
    }

    button:active {
        background-color: #6b6b6b;
    }

    .play-pause::before {
        content: '▶';
        margin-right: 8px;
    }

    .paused::before {
        content: '⏸';
    }
</style>
</head>
<body>
<canvas id="life" width="400" height="400"></canvas>
<div class="controls">
    <button id="step">Step</button>
    <button id="play" class="btn play-pause">Play</button>
    <button id="random">Random</button>
    <button id="clear">Clear</button>
</div>

<script>
document.addEventListener('DOMContentLoaded', () => {
    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d');

    let w = 40, h = 40;
    const CELL_SIZE = 10; // Each cell is 10x10 pixels for 400px grid.

    let grid = new Uint8Array(w * h);
    let drawing = false;
    let playingInterval;
    let isPlaying = false;

    function draw() {
        ctx.fillStyle = '#0d0d0d';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
                if (grid[y * w + x] === 1) {
                    ctx.fillStyle = '#00ff9e'; // Bright green alive cells
                    ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE - 1, CELL_SIZE - 1);
                }
            }
        }

        // Add grid lines for better visibility
        ctx.strokeStyle = '#3a3a3a';
        ctx.lineWidth = 1;

        // Vertical lines
        for (let x = 0; x <= w; x++) {
            const posX = x * CELL_SIZE;
            ctx.beginPath();
            ctx.moveTo(posX, 0);
            ctx.lineTo(posX, h * CELL_SIZE);
            ctx.stroke();
        }

        // Horizontal lines
        for (let y = 0; y <= h; y++) {
            const posY = y * CELL_SIZE;
            ctx.beginPath();
            ctx.moveTo(0, posY);
            ctx.lineTo(w * CELL_SIZE, posY);
            ctx.stroke();
        }
    }

    canvas.addEventListener('mousedown', (e) => {
        drawing = true;
        handleCanvasClick(e);
    });

    document.addEventListener('mouseup', () => {
        drawing = false;
    });

    canvas.addEventListener('mousemove', (e) => {
        if (!drawing) return;
        handleCanvasClick(e);
    });

    function handleCanvasClick(e) {
        const rect = canvas.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        const xCell = Math.floor(mouseX / CELL_SIZE);
        const yCell = Math.floor(mouseY / CELL_SIZE);

        if (xCell < 0 || yCell < 0 || xCell >= w || yCell >= h) return;

        grid[yCell * w + xCell] ^= 1; // Toggle cell state
        draw();
    }

    function computeNextGen() {
        const next = new Uint8Array(w * h);

        for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
                let neighbors = 0;

                for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                        if (dx === 0 && dy === 0) continue; // Skip self

                        const nx = x + dx;
                        const ny = y + dy;

                        if (nx >= 0 && ny >= 0 && nx < w && ny < h) {
                            neighbors += grid[ny * w + nx];
                        }
                    }
                }

                const current = grid[y * w + x];

                if (current === 1) { // Live cell
                    next[y * w + x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
                } else { // Dead cell
                    next[y * w + x] = (neighbors === 3) ? 1 : 0;
                }
            }
        }

        return next;
    }

    document.getElementById('step').addEventListener('click', () => window.life.step());

    document.getElementById('play').addEventListener('click', function() {
        isPlaying = !isPlaying;
        if (isPlaying) {
            playingInterval = setInterval(() => window.life.step(), 100);
            this.classList.add('paused');
        } else {
            clearInterval(playingInterval);
            this.classList.remove('paused');
        }
    });

    document.getElementById('random').addEventListener('click', () => window.life.random());
    document.getElementById('clear').addEventListener('click', () => window.life.clear());

    // Define the global life API object
    window.life = {
        w: w,
        h: h,

        get(x, y) {
            if (x < 0 || y < 0 || x >= this.w || y >= this.h) return 0;
            return grid[y * this.w + x] ? 1 : 0;
        },

        set(x, y, v) {
            if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
            grid[y * this.w + x] = v ? 1 : 0;
            draw();
        },

        step() {
            const nextGen = computeNextGen();
            for (let i = 0; i < w * h; i++) {
                grid[i] = nextGen[i];
            }
            draw();
        },

        clear() {
            grid.fill(0);
            draw();
        },

        random() {
            for (let i = 0; i < w * h; i++) {
                grid[i] = Math.random() > 0.5 ? 1 : 0;
            }
            draw();
        }
    };

    // Initial rendering
    draw();
});
</script>
</body>
</html>
